// App Engine State
type EngineState = 'STOPPED' | 'RUNNING';
type DatePickerViewMode = 'CALENDAR' | 'YEAR_SELECT' | 'TEXT_INPUT';

let engine: QuantumWormholeEngine | null = null;
let engineState: EngineState = 'STOPPED';
let animationFrameId: number | null = null;
let lastFrameTime = performance.now();
let frameCount = 0;
let fpsTimer = performance.now();
let timeOffset = 0;
let wasRunningBeforeHide = false;

// 彩蛋 / 音效
let activeEgg: EasterEgg | null = null;
const audio = new AudioManager('audio/');
const SOUND_STORAGE_KEY = 'qw.sound';

// M3 DatePicker State
let currentSelectedDate = new Date(2000, 0, 1);
let activePickerYear = 2000;
let activePickerMonth = 0;
let tempSelectedDate = new Date(2000, 0, 1);
let datePickerMode: DatePickerViewMode = 'CALENDAR';

/* ------------------------------------------------------------------ */
/* 工具函数                                                            */
/* ------------------------------------------------------------------ */

// Compute SHA-256 Hash for input seed display
async function computeHash(str: string): Promise<string> {
  const encoder = new TextEncoder();
  const data = encoder.encode(str);
  const hashBuffer = await crypto.subtle.digest('SHA-256', data);
  const hashArray = Array.from(new Uint8Array(hashBuffer));
  return hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
}

// 32bit 哈希（旧版 getHash，用于音效种子）
function getSeed(name: string, dob: string): number {
  const input = `${name}${dob}`;
  let hash = 0;
  for (let i = 0; i < input.length; i++) {
    const chr = input.charCodeAt(i);
    hash = (hash << 5) - hash + chr;
    hash |= 0;
  }
  return hash;
}

/* ------------------------------------------------------------------ */
/* 音效                                                                */
/* ------------------------------------------------------------------ */

function initSoundToggle() {
  const saved = localStorage.getItem(SOUND_STORAGE_KEY);
  const enabled = saved === null ? true : saved === '1';
  audio.setEnabled(enabled);
  syncSoundIcon();
  btnSound.addEventListener('click', () => {
    audio.setEnabled(!audio.enabled);
    localStorage.setItem(SOUND_STORAGE_KEY, audio.enabled ? '1' : '0');
    syncSoundIcon();
    showToast(audio.enabled ? t('app.soundOn') : t('app.soundOff'));
  });
}

function syncSoundIcon() {
  soundIcon.textContent = audio.enabled ? 'volume_up' : 'volume_off';
  btnSound.title = audio.enabled ? t('app.soundOff') : t('app.soundOn');
}

